//! Replays the Go-recorded `policy.ContextProvider.BuildContext` field mapping
//! and the policy outcomes it produces (`testdata/port/mcp/policy-build-context.json`,
//! generated by `internal/policy/context_fixture_generator_test.go`).
//!
//! Rust must never be more permissive than Go: every deny/prompt/biometry
//! rule that Go's real context matches has to match here too.

use std::collections::BTreeMap;

use serde::Deserialize;
use symvault_core::policy::{Action, Conditions, Engine, Policy, Rule};
use symvault_mcp::policy_context::{ContextProvider, RuntimeFacts, assemble};

const FIXTURE: &str = include_str!("../../../testdata/port/mcp/policy-build-context.json");

#[derive(Deserialize)]
struct Fixture {
    schema_version: u8,
    oracle: Oracle,
    cases: Vec<Case>,
    eval_cases: Vec<EvalCase>,
}

#[derive(Deserialize)]
struct Oracle {
    commit_sha: String,
    source_files: Vec<String>,
    source_digest: String,
}

#[derive(Clone, Deserialize)]
struct Input {
    name: String,
    home: String,
    #[serde(default)]
    home_unset: bool,
    working_dir: String,
    git_branch: String,
    agent_id: String,
    path: String,
    action_type: String,
    tags: Option<Vec<String>>,
}

#[derive(Deserialize)]
struct Case {
    #[serde(flatten)]
    input: Input,
    context: Output,
}

#[derive(Deserialize)]
struct Output {
    agent_id: String,
    path: String,
    tags: Option<Vec<String>>,
    working_dir: String,
    home_dir: String,
    env_vars: BTreeMap<String, String>,
    action_type: String,
    tool_name: String,
}

#[derive(Deserialize)]
struct FixtureRule {
    name: String,
    #[serde(default)]
    priority: i32,
    action: String,
    #[serde(default)]
    path: String,
    #[serde(default)]
    working_dir: String,
    #[serde(default)]
    action_type: String,
    #[serde(default)]
    env: BTreeMap<String, String>,
    #[serde(default)]
    allowed_tools: Vec<String>,
}

#[derive(Deserialize)]
struct EvalCase {
    name: String,
    rules: Vec<FixtureRule>,
    input: Input,
    action: String,
    rule_name: String,
    matched: bool,
}

fn fixture() -> Fixture {
    serde_json::from_str(FIXTURE).expect("decode Go-generated build-context fixture")
}

fn rust_context(input: &Input) -> symvault_core::policy::EvalContext {
    assemble(
        &input.agent_id,
        &input.path,
        &input.action_type,
        input.tags.as_deref().unwrap_or(&[]),
        &RuntimeFacts {
            working_dir: input.working_dir.clone(),
            home_dir: if input.home_unset {
                String::new()
            } else {
                input.home.clone()
            },
            git_branch: input.git_branch.clone(),
        },
        symvault_core::policy::UtcTime::from_hms(12, 0, 0).unwrap(),
    )
}

fn action(name: &str) -> Action {
    match name {
        "allow" => Action::Allow,
        "deny" => Action::Deny,
        "prompt" => Action::Prompt,
        "require_biometry" => Action::RequireBiometry,
        other => panic!("unknown action {other}"),
    }
}

#[test]
fn fixture_has_pinned_provenance() {
    let fixture = fixture();
    assert_eq!(fixture.schema_version, 1);
    assert_eq!(fixture.oracle.commit_sha.len(), 40);
    assert_eq!(fixture.oracle.source_digest.len(), 64);
    assert_eq!(
        fixture.oracle.source_files,
        [
            "internal/policy/context.go",
            "internal/policy/engine.go",
            "internal/policy/types.go",
            "internal/secrets/filter.go",
        ]
    );
    assert_eq!(fixture.cases.len(), 12);
    assert_eq!(fixture.eval_cases.len(), 17);
}

#[test]
fn build_context_fields_match_go() {
    for case in fixture().cases {
        let name = &case.input.name;
        let got = rust_context(&case.input);
        let want = &case.context;
        assert_eq!(got.agent_id, want.agent_id, "{name}: agent_id");
        assert_eq!(got.path, want.path, "{name}: path");
        assert_eq!(
            Some(got.tags.clone()).filter(|tags| !tags.is_empty()),
            want.tags.clone(),
            "{name}: tags"
        );
        assert_eq!(got.working_dir, want.working_dir, "{name}: working_dir");
        assert_eq!(got.home_dir, want.home_dir, "{name}: home_dir");
        assert_eq!(got.env_vars, want.env_vars, "{name}: env_vars");
        assert_eq!(got.action_type, want.action_type, "{name}: action_type");
        assert_eq!(got.tool_name, want.tool_name, "{name}: tool_name");
        assert_eq!(got.tool_name, "", "{name}: Go never sets ToolName");
    }
}

#[test]
fn policy_outcomes_through_build_context_match_go() {
    for case in fixture().eval_cases {
        let rules = case
            .rules
            .iter()
            .map(|rule| Rule {
                name: rule.name.clone(),
                priority: rule.priority,
                action: action(&rule.action),
                conditions: Conditions {
                    path: rule.path.clone(),
                    working_dir: rule.working_dir.clone(),
                    action: rule.action_type.clone(),
                    env_vars: rule.env.clone(),
                    allowed_tools: rule.allowed_tools.clone(),
                    ..Conditions::default()
                },
            })
            .collect();
        let engine = Engine::new([Policy {
            version: "1.0".into(),
            description: String::new(),
            rules,
        }]);
        let result = engine.evaluate(rust_context(&case.input));
        assert_eq!(
            (result.action, result.rule_name.as_str(), result.matched),
            (action(&case.action), case.rule_name.as_str(), case.matched),
            "{}",
            case.name
        );
    }
}

#[test]
fn runtime_provider_resolves_unresolvable_git_dir_to_empty_branch() {
    // Mirrors the Go "unresolvable_git_branch" case through the real runtime
    // path: git fails in a directory that does not exist, so the branch is "".
    let mut provider = ContextProvider::new();
    provider.set_working_dir("/nonexistent-policy-fixture-dir");
    let got = provider.build_context("agent", "p", "get", &[]);
    assert_eq!(got.env_vars["GIT_BRANCH"], "");
    assert_eq!(got.working_dir, "/nonexistent-policy-fixture-dir");
    assert_eq!(got.tool_name, "");
}
